urlset:
{% set root = site.url ~ site.base_path %}
{% for page in ['/', '/blogs/', '/about/', '/tags/'] %}
{{ root }}{{ page }}
{% endfor %}
{% for p in posts %}
{{ root }}/blogs/{{ p.slug }}/{{ (p.updated or p.date).isoformat() }}
{% endfor %}
{% for t in tags %}
{{ root }}/tags/{{ t.slug }}/
{% endfor %}
